pub fn arccosh(x: Vec<f32>) -> Vec<f32> {
    // Allocate the result vector with the same capacity as the input length.
    let n = x.len();
    let mut result = Vec::with_capacity(n);

    // Process each element by index, from 0 to n - 1 inclusive.
    // At each iteration, we've processed `idx` elements and pushed
    // `idx` results so far, maintaining the specified invariant.
    let mut idx = 0;
    while idx < n {
        // Compute the inverse hyperbolic cosine (arccosh) of x[idx].
        // Note: f32::acosh is a standard library method.
        let y = x[idx].acosh();
        result.push(y);

        idx += 1;
    }

    // Return the newly built vector of the same length as `x`.
    result
}

